const pptxgen = require('pptxgenjs');
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaCheckCircle } = require("react-icons/fa");

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

async function createDeck() {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';

  const BG_COLOR = "0F172A"; 
  const TEXT_MAIN = "F8FAFC"; 
  const TEXT_MUTED = "94A3B8"; 
  const ACCENT_PRIMARY = "3B82F6"; 
  const ACCENT_SECONDARY = "10B981"; 
  const CARD_BG = "1E293B"; 

  pres.defineSlideMaster({
    title: 'MASTER_SLIDE',
    background: { color: BG_COLOR },
    objects: [
      { rect: { x: 0, y: 0, w: '100%', h: 0.1, fill: { color: ACCENT_PRIMARY } } },
      { text: { text: "OSSInsight Data · Past 24 Hours", options: { x: 0.5, y: 5.2, w: 9, h: 0.3, color: TEXT_MUTED, fontSize: 10, align: 'left', fontFace: 'Arial' } } }
    ]
  });

  const addTitle = (slide, title) => {
    slide.addText(title, { x: 0.5, y: 0.4, w: 9, h: 0.6, fontSize: 28, bold: true, color: TEXT_MAIN, fontFace: 'Arial' });
  };

  const iconCheck = await iconToBase64Png(FaCheckCircle, "#" + ACCENT_SECONDARY);

  // SLIDE 1
  let slide1 = pres.addSlide();
  slide1.background = { color: BG_COLOR };
  slide1.addText("GitHub Trending Repos Snapshot", { x: 0.5, y: 1.5, w: 9, h: 0.8, fontSize: 24, color: ACCENT_PRIMARY, bold: true, fontFace: 'Arial' });
  slide1.addText("The Rise of AI Coding Agents & Claude Code Skills", { x: 0.5, y: 2.2, w: 9, h: 1.2, fontSize: 44, color: TEXT_MAIN, bold: true, fontFace: 'Arial Black', breakLine: true });
  slide1.addShape(pres.shapes.LINE, { x: 0.5, y: 3.5, w: 1.5, h: 0, line: { color: ACCENT_SECONDARY, width: 4 } });
  slide1.addText("Based on OSSInsight's 10.6B+ GitHub events dataset\nPast 24 Hours Data", { x: 0.5, y: 3.8, w: 9, h: 1, fontSize: 18, color: TEXT_MUTED, fontFace: 'Arial' });

  // SLIDE 2
  let slide2 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
  addTitle(slide2, "OSSInsight Tracks 10.6 Billion GitHub Events in Real Time");
  slide2.addText("OSSInsight is a real-time analytics platform that tracks developer activity to provide deep insights into open-source repositories.", { x: 0.5, y: 1.2, w: 9, h: 0.8, fontSize: 18, color: TEXT_MUTED });
  [
    { num: "10.6B+", label: "GitHub Events Tracked" },
    { num: "Real-time", label: "Data Pipeline" },
    { num: "Top 20", label: "Repositories Analyzed" }
  ].forEach((stat, i) => {
    let xOffset = 0.5 + i * 3.1;
    slide2.addShape(pres.shapes.RECTANGLE, { x: xOffset, y: 2.5, w: 2.8, h: 2, fill: { color: CARD_BG } });
    slide2.addText(stat.num, { x: xOffset, y: 2.8, w: 2.8, h: 0.8, fontSize: 40, bold: true, color: ACCENT_PRIMARY, align: 'center' });
    slide2.addText(stat.label, { x: xOffset, y: 3.6, w: 2.8, h: 0.5, fontSize: 16, color: TEXT_MAIN, align: 'center' });
  });

  // SLIDE 3
  let slide3 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
  addTitle(slide3, "hermes-agent Leads with 1,347 Stars — Top 5 Repos");
  slide3.addText("Top 5 Repos by Total Score (Past 24 Hours)", { x: 0.5, y: 1.0, w: 9, h: 0.5, fontSize: 16, color: TEXT_MUTED });
  slide3.addChart(pres.charts.BAR, [{
    name: "Stars",
    labels: ["hermes-agent", "graphify", "awesome-design-md", "caveman", "claude-code-best-practice"],
    values: [1347, 742, 615, 300, 304]
  }], {
    x: 0.5, y: 1.6, w: 5.5, h: 3.4, barDir: "bar",
    chartColors: [ACCENT_PRIMARY, "334155", "334155", "334155", "334155"],
    chartArea: { fill: { color: "000000", transparency: 100 } },
    plotArea: { fill: { color: "000000", transparency: 100 } },
    catAxisLabelColor: TEXT_MAIN, valAxisLabelColor: TEXT_MUTED,
    valGridLine: { color: CARD_BG, size: 1 }, catGridLine: { style: "none" },
    showValue: true, dataLabelColor: TEXT_MAIN, showLegend: false
  });
  let tableData3 = [
    [{text:"Repository", options:{color:TEXT_MAIN, bold:true}}, {text:"Forks", options:{color:TEXT_MAIN, bold:true}}, {text:"Pushes", options:{color:TEXT_MAIN, bold:true}}, {text:"PRs", options:{color:TEXT_MAIN, bold:true}}],
    ["hermes-agent", "101", "42", "78"],
    ["graphify", "50", "6", "5"],
    ["awesome-design-md", "48", "1", "0"],
    ["caveman", "11", "1", "1"],
    ["claude-code-best-practice", "23", "0", "0"]
  ];
  slide3.addTable(tableData3, { x: 6.2, y: 1.6, w: 3.5, colW: [1.7, 0.6, 0.6, 0.6], border: { pt: 1, color: "334155" }, fill: { color: CARD_BG }, color: TEXT_MAIN, fontSize: 12, rowH: [0.4, 0.5, 0.5, 0.5, 0.5, 0.5] });

  // SLIDE 4
  let slide4 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
  addTitle(slide4, "Python and TypeScript Dominate Language Mix");
  slide4.addChart(pres.charts.DOUGHNUT, [{
    name: "Languages",
    labels: ["Python (35%)", "TypeScript (20%)", "HTML (10%)", "Rust (10%)", "Swift (10%)", "Shell, Java, Unspec. (15%)"],
    values: [7, 4, 2, 2, 2, 3]
  }], {
    x: 0.5, y: 1.5, w: 5, h: 3.5,
    chartColors: [ACCENT_PRIMARY, ACCENT_SECONDARY, "F59E0B", "E11D48", "8B5CF6", "334155"],
    chartArea: { fill: { color: "000000", transparency: 100 } },
    plotArea: { fill: { color: "000000", transparency: 100 } },
    showLegend: true, legendPos: "r", legendColor: TEXT_MAIN, holeSize: 50
  });
  slide4.addText("Python's outsized 35% share reflects its status as the primary language for the AI/ML ecosystem. TypeScript (20%) is the runner-up, driving agent UIs and developer experience layers.", { x: 6.0, y: 2.0, w: 3.5, h: 2, fontSize: 18, color: TEXT_MUTED, align: "left" });

  // SLIDE 5
  let slide5 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
  addTitle(slide5, "14 of 20 Trending Repos Are AI Projects");
  slide5.addText("AI Coding Agents & Claude Code projects account for ~70% of the top 20 trending repos—an unprecedented concentration.", { x: 0.5, y: 1.2, w: 9, h: 0.8, fontSize: 18, color: TEXT_MUTED });
  slide5.addChart(pres.charts.BAR, [{
    name: "Repositories",
    labels: ["AI Coding Agents & Skills", "Claude Code Ecosystem", "Developer Utilities", "AI Infrastructure"],
    values: [10, 5, 4, 3]
  }], {
    x: 0.5, y: 2.0, w: 6, h: 3, barDir: "bar",
    chartColors: [ACCENT_PRIMARY, ACCENT_SECONDARY, "334155", "334155"],
    chartArea: { fill: { color: "000000", transparency: 100 } },
    plotArea: { fill: { color: "000000", transparency: 100 } },
    catAxisLabelColor: TEXT_MAIN, valAxisLabelColor: TEXT_MUTED,
    valGridLine: { color: "334155", size: 1 }, catGridLine: { style: "none" },
    showValue: true, dataLabelColor: TEXT_MAIN, showLegend: false
  });
  slide5.addShape(pres.shapes.RECTANGLE, { x: 7.0, y: 2.2, w: 2.5, h: 2.5, fill: { color: CARD_BG } });
  slide5.addText("70%", { x: 7.0, y: 2.6, w: 2.5, h: 0.8, fontSize: 54, color: ACCENT_SECONDARY, bold: true, align: "center" });
  slide5.addText("Relate directly to AI coding assistance", { x: 7.2, y: 3.5, w: 2.1, h: 0.8, fontSize: 16, color: TEXT_MAIN, align: "center" });

  // SLIDE 6
  let slide6 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
  addTitle(slide6, "Claude Code Spawns an Ecosystem");
  slide6.addText("Skills, Guides, Switches, and Best Practices", { x: 0.5, y: 1.0, w: 9, h: 0.5, fontSize: 18, color: TEXT_MUTED });
  slide6.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.8, w: 4.2, h: 3.2, fill: { color: CARD_BG } });
  slide6.addText("Core Ecosystem Tools (5)", { x: 0.7, y: 2.0, w: 3.8, h: 0.4, fontSize: 20, bold: true, color: ACCENT_PRIMARY });
  slide6.addText([
    { text: "claude-code-best-practice", options: { bullet: true, breakLine: true } },
    { text: "claude-howto", options: { bullet: true, breakLine: true } },
    { text: "cc-switch", options: { bullet: true, breakLine: true } },
    { text: "caveman", options: { bullet: true, breakLine: true } },
    { text: "learn-claude-code", options: { bullet: true } }
  ], { x: 0.7, y: 2.5, w: 3.8, h: 2.2, fontSize: 16, color: TEXT_MAIN });
  slide6.addShape(pres.shapes.RECTANGLE, { x: 5.3, y: 1.8, w: 4.2, h: 3.2, fill: { color: CARD_BG } });
  slide6.addText("Broader Synergies (7+)", { x: 5.5, y: 2.0, w: 3.8, h: 0.4, fontSize: 20, bold: true, color: ACCENT_SECONDARY });
  slide6.addText([
    { text: "Includes multi-tool switchers", options: { bullet: true, breakLine: true } },
    { text: "Cross-listed with AI coding agents", options: { bullet: true, breakLine: true } },
    { text: "agent-skills", options: { bullet: true, breakLine: true } },
    { text: "oh-my-codex", options: { bullet: true, breakLine: true } },
    { text: "Rapid community formation", options: { bullet: true } }
  ], { x: 5.5, y: 2.5, w: 3.8, h: 2.2, fontSize: 16, color: TEXT_MAIN });

  // SLIDE 7
  let slide7 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
  addTitle(slide7, "hermes-agent Draws 78 PRs and 42 Pushes");
  slide7.addText("Community Activity Varies Widely Across the Top 20", { x: 0.5, y: 1.0, w: 9, h: 0.5, fontSize: 18, color: TEXT_MUTED });
  slide7.addChart(pres.charts.BAR, [
    { name: "Pull Requests", labels: ["hermes-agent", "multica", "oh-my-codex", "rtk", "graphify"], values: [78, 7, 2, 5, 5] },
    { name: "Pushes", labels: ["hermes-agent", "multica", "oh-my-codex", "rtk", "graphify"], values: [42, 35, 10, 3, 6] }
  ], {
    x: 0.5, y: 1.6, w: 6.5, h: 3.4, barDir: "col",
    chartColors: [ACCENT_PRIMARY, ACCENT_SECONDARY],
    chartArea: { fill: { color: "000000", transparency: 100 } },
    plotArea: { fill: { color: "000000", transparency: 100 } },
    catAxisLabelColor: TEXT_MAIN, valAxisLabelColor: TEXT_MUTED,
    valGridLine: { color: "334155", size: 1 }, catGridLine: { style: "none" },
    showValue: true, dataLabelColor: TEXT_MAIN, showLegend: true, legendPos: "r", legendColor: TEXT_MAIN
  });
  slide7.addShape(pres.shapes.RECTANGLE, { x: 7.2, y: 1.6, w: 2.3, h: 3.4, fill: { color: CARD_BG } });
  slide7.addText("Zero PRs", { x: 7.4, y: 2.0, w: 1.9, h: 0.8, fontSize: 24, bold: true, color: "E11D48", align: "center" });
  slide7.addText("8 of the 20 trending repos have 0 PRs, suggesting early-stage viral projects.", { x: 7.4, y: 2.8, w: 1.9, h: 1.5, fontSize: 16, color: TEXT_MAIN, align: "center" });

  // SLIDE 8
  let slide8 = pres.addSlide({ masterName: 'MASTER_SLIDE' });
  addTitle(slide8, "Key Takeaways: AI Agents Are GitHub's Hottest Category");
  [
    "AI coding agents dominate GitHub trending: 70% of top repos are AI tools.",
    "Claude Code has spawned a full ecosystem overnight.",
    "Python leads (35%), but TypeScript is the strong runner-up (20%).",
    "Community engagement is top-heavy (hermes-agent dominates).",
    "Token efficiency is a hot sub-theme as AI tools scale."
  ].forEach((text, i) => {
    slide8.addImage({ data: iconCheck, x: 0.8, y: 1.6 + i * 0.7, w: 0.4, h: 0.4 });
    slide8.addText(text, { x: 1.4, y: 1.55 + i * 0.7, w: 8, h: 0.5, fontSize: 18, color: TEXT_MAIN });
  });

  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
}

createDeck().catch(console.error);

